size_t cell = ckh_bucket_search(ckh, primary_bucket, key);
if (cell != SIZE_T_MAX) {
    return cell;
}

size_t secondary_bucket = hashes[1] & ((static_cast<size_t>(1) << ckh->lg_curbuckets) - 1);
cell = ckh_bucket_search(ckh, secondary_bucket, key);
return cell;

